// ============================================
// 📝 BLOG TOPICS MEMORY - ADD YOUR IDEAS HERE!
// ============================================
// Add topics you want AI to research and write about.
// The workflow will pick the most relevant one.

const blogTopics = [
  {
    topic: "Latest Bollywood songs released",
    keywords: ["bollywood", "hindi songs", "new releases"],
    priority: "high",
    category: "Music News"
  },
  {
    topic: "Trending wedding sangeet songs",
    keywords: ["sangeet", "wedding songs", "dance songs"],
    priority: "high",
    category: "Wedding Music"
  },
  {
    topic: "Best romantic songs for anniversaries",
    keywords: ["anniversary", "romantic", "love songs"],
    priority: "medium",
    category: "Romantic Music"
  },
  {
    topic: "K-pop and international music releases",
    keywords: ["kpop", "international", "english songs"],
    priority: "medium",
    category: "International Music"
  },
  {
    topic: "Birthday song ideas and party music",
    keywords: ["birthday", "party songs", "celebration"],
    priority: "medium",
    category: "Celebration Music"
  },
  {
    topic: "Regional Indian music - Tamil, Telugu, Punjabi hits",
    keywords: ["tamil songs", "telugu songs", "punjabi music"],
    priority: "low",
    category: "Regional Music"
  }
];

// Generate date info
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

const formattedDate = yesterday.toISOString().split('T')[0];
const readableDate = yesterday.toLocaleDateString('en-US', {
  weekday: 'long',
  month: 'long',
  day: 'numeric',
  year: 'numeric'
});

const shortDate = yesterday.toLocaleDateString('en-US', {
  month: 'short',
  day: 'numeric',
  year: 'numeric'
});

// Pick topic based on day of week for variety
const dayOfWeek = new Date().getDay();
const topicIndex = dayOfWeek % blogTopics.length;
const selectedTopic = blogTopics[topicIndex];

// Build search queries combining topic with date
const searchQueries = [
  `${selectedTopic.topic} ${formattedDate}`,
  ...selectedTopic.keywords.map(kw => `${kw} ${formattedDate} India`),
  `latest music news India ${formattedDate}`,
  `trending songs ${formattedDate}`
];

// Image search queries for Unsplash
const imageSearchQueries = [
  "music concert stage lights",
  "bollywood dance performance",
  "wedding sangeet celebration india",
  "music studio recording",
  "headphones vinyl aesthetic",
  "DJ party celebration"
];

return {
  json: {
    // Date info
    search_date: formattedDate,
    readable_date: readableDate,
    short_date: shortDate,
    month_year: yesterday.toLocaleDateString('en-US', { month: 'long', year: 'numeric' }),

    // Topic info
    selected_topic: selectedTopic,
    all_topics: blogTopics,

    // Search queries
    search_queries: searchQueries,
    image_queries: imageSearchQueries,

    // Metadata
    workflow_run_id: `run_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
};

