const input = $input.first();
const memoryData = $('📝 Blog Topics Memory Bank').first().json;

try {
  const responseBody = input.json.body || input.json;
  let researchContent = '';

  if (responseBody.choices && responseBody.choices[0]) {
    researchContent = responseBody.choices[0].message?.content || '';
  } else if (typeof responseBody === 'string') {
    researchContent = responseBody;
  } else {
    researchContent = JSON.stringify(responseBody);
  }

  // Validate content
  if (researchContent.length < 100) {
    throw new Error('Research content too short');
  }

  return {
    json: {
      research_content: researchContent,
      selected_topic: memoryData.selected_topic,
      date_data: {
        search_date: memoryData.search_date,
        readable_date: memoryData.readable_date,
        short_date: memoryData.short_date,
        month_year: memoryData.month_year
      },
      image_queries: memoryData.image_queries,
      content_length: researchContent.length,
      status: 'success'
    }
  };

} catch (error) {
  return {
    json: {
      research_content: `Topic: ${memoryData.selected_topic.topic}. Research data unavailable, generating content based on topic.`,
      selected_topic: memoryData.selected_topic,
      date_data: {
        search_date: memoryData.search_date,
        readable_date: memoryData.readable_date,
        short_date: memoryData.short_date,
        month_year: memoryData.month_year
      },
      image_queries: memoryData.image_queries,
      content_length: 0,
      status: 'fallback',
      error: error.message
    }
  };
}

const items = $input.all();
const researchData = $('📊 Parse Research Results').first().json;

// Extract images from both sources
let allImages = [];

items.forEach(item => {
  // Unsplash images
  if (item.json?.results) {
    item.json.results.forEach(img => {
      if (img.urls?.regular) {
        allImages.push({
          url: img.urls.regular,
          thumb: img.urls.thumb || img.urls.small,
          alt: img.alt_description || 'Music related image',
          credit: `Photo by ${img.user?.name || 'Unknown'} on Unsplash`,
          source: 'unsplash',
          width: img.width,
          height: img.height
        });
      }
    });
  }

  // Pexels images
  if (item.json?.photos) {
    item.json.photos.forEach(img => {
      if (img.src?.large) {
        allImages.push({
          url: img.src.large,
          thumb: img.src.tiny || img.src.small,
          alt: img.alt || 'Music related image',
          credit: `Photo from Pexels by ${img.photographer || 'Unknown'}`,
          source: 'pexels',
          width: img.width,
          height: img.height
        });
      }
    });
  }
});

// Select best featured image (prefer landscape, good resolution)
const featuredImage = allImages.length > 0 
  ? allImages[0] 
  : {
      url: 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=1200&h=630&fit=crop',
      thumb: 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=400&h=300&fit=crop',
      alt: 'Music and entertainment',
      credit: 'Default music image',
      source: 'default'
    };

// Get additional images for content
const contentImages = allImages.slice(1, 4);

return {
  json: {
    research_content: researchData.research_content,
    selected_topic: researchData.selected_topic,
    date_data: researchData.date_data,
    featured_image: featuredImage,
    content_images: contentImages,
    all_images: allImages,
    images_found: allImages.length
  }
};

const geminiResponse = $input.first();
const imageData = $('🎨 Process & Select Best Images').first().json;

// Extract blog content
let blogContent = '';
try {
  const response = geminiResponse.json;
  if (response.content) {
    blogContent = response.content;
  } else if (response.text) {
    blogContent = response.text;
  } else if (response.candidates && response.candidates[0]) {
    blogContent = response.candidates[0].content?.parts?.[0]?.text || '';
  } else if (typeof response === 'string') {
    blogContent = response;
  } else {
    blogContent = JSON.stringify(response);
  }
} catch (e) {
  blogContent = 'Blog content generation failed. Please try again.';
}

// Insert featured image at the top of content after the title
if (imageData.featured_image.url) {
  const imageMarkdown = `\n\n![${imageData.featured_image.alt}](${imageData.featured_image.url})\n*${imageData.featured_image.credit}*\n\n`;
  // Insert after first heading
  blogContent = blogContent.replace(/(# .+\n)/, `$1${imageMarkdown}`);
}

// Insert additional images throughout content
if (imageData.content_images && imageData.content_images.length > 0) {
  let imgIndex = 0;
  blogContent = blogContent.replace(/(### \d+\..+\n)/g, (match) => {
    if (imageData.content_images[imgIndex]) {
      const img = imageData.content_images[imgIndex];
      imgIndex++;
      return `${match}\n![${img.alt}](${img.url})\n*${img.credit}*\n\n`;
    }
    return match;
  });
}

// Generate SEO metadata
const dateData = imageData.date_data;
const topic = imageData.selected_topic;

const slug = `${topic.topic.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${dateData.search_date}`;
const title = `${topic.topic} - ${dateData.short_date} | OwnSangeet`;
const excerpt = `Discover ${topic.topic.toLowerCase()} on ${dateData.readable_date}. From Bollywood to international hits, find the perfect inspiration for your custom song at OwnSangeet.`;
const tags = `${topic.keywords.join(', ')}, Music News, ${dateData.month_year}, OwnSangeet, Custom Songs`;

return {
  json: {
    // Blog post data
    title: title,
    slug: slug,
    content: blogContent,
    excerpt: excerpt,
    tags: tags,
    featuredImageUrl: imageData.featured_image.url,

    // Metadata
    topic: topic,
    date_data: dateData,
    images_used: {
      featured: imageData.featured_image,
      content: imageData.content_images
    },

    // Stats
    content_length: blogContent.length,
    word_count: blogContent.split(/\s+/).length,
    generated_at: new Date().toISOString()
  }
};

