const publishResponse = $input.first().json;
const blogData = $('📦 Format Final Blog Post').first().json;

const responseBody = publishResponse.body || publishResponse;
const postData = responseBody.post || responseBody;

return {
  json: {
    status: '✅ SUCCESS',
    post_id: postData.id,
    post_title: postData.title || blogData.title,
    post_slug: postData.slug || blogData.slug,
    post_url: `https://ownsangeet.com/blog/${postData.slug || blogData.slug}`,
    featured_image: blogData.featuredImageUrl,
    topic: blogData.topic.topic,
    category: blogData.topic.category,
    word_count: blogData.word_count,
    published_at: new Date().toISOString()
  }
};

const input = $input.first().json;
const blogData = $('📦 Format Final Blog Post').first().json;

return {
  json: {
    status: '❌ FAILED',
