console.log('URL:', successData.post_url);
console.log('Topic:', successData.topic);
console.log('Category:', successData.category);
console.log('Word Count:', successData.word_count);
console.log('Published At:', successData.published_at);
console.log('================================\n');

return {
  json: {
    ...successData,
    search_engines_notified: ['Google', 'Bing'],
    workflow_completed_at: new Date().toISOString()
  }
};
